{"file_path":"src/parse.js","content":"/**
 * Parsing of the three-document standard input format used by the CLI.
 */

/**
 * Split raw standard input into lines, dropping the empty tail a trailing
 * newline leaves.
 * @param {string} input
 * @returns {string[]}
 */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

/**
 * Split a flat list of lines into exactly three documents, separated by
 * lines that are exactly `%%%`.
 * @param {string[]} lines
 * @returns {[string[], string[], string[]] | null} null when the input does
 *   not hold exactly three documents.
 */
export function splitDocuments(lines) {
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }
  if (docs.length !== 3) return null
  return [docs[0], docs[1], docs[2]]
}
"}

