{"file_path":"src/diff.js","content":"/**
 * Longest-common-subsequence diffing between a base document and one side,
 * with a deterministic tie-break so that, among equally long subsequences,
 * the one whose matches occur earliest is chosen.
 */

/**
 * @typedef {object} Change
 * @property {number} baseStart inclusive start index into base
 * @property {number} baseEnd exclusive end index into base
 * @property {number} sideStart inclusive start index into the side
 * @property {number} sideEnd exclusive end index into the side
 */

/**
 * Compute the changes needed to turn `base` into `side`, using the
 * earliest-match longest common subsequence.
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Change[]}
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const advanceBase = dp[i + 1][j]
        const advanceSide = dp[i][j + 1]
        dp[i][j] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let baseStart = 0
  let sideStart = 0

  const flush = (baseEnd, sideEnd) => {
    if (baseEnd > baseStart || sideEnd > sideStart) {
      changes.push({ baseStart, baseEnd, sideStart, sideEnd })
    }
  }

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++
      j++
      baseStart = i
      sideStart = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  flush(n, m)

  return changes
}
"}

