 * Build the ordered list of merge regions (stable and changed) covering the
 * whole base document.
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Array<object>} regions, each either
 *   `{ type: 'stable', lines }` or
 *   `{ type: 'resolved', kind: 'mine'|'theirs'|'both', lines, baseLines, mineLines, theirsLines }` or
 *   `{ type: 'resolved', kind: 'conflict', mineLines, baseLines, theirsLines }`
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const all = [...mineChanges, ...theirChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const clusters = []
  for (const change of all) {
    const last = clusters[clusters.length - 1]
    if (last && change.baseStart <= last.baseEnd) {
      last.baseEnd = Math.max(last.baseEnd, change.baseEnd)
      last.changes.push(change)
    } else {
      clusters.push({ baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const cluster of clusters) {
    if (cluster.baseStart > pos) {
      regions.push({ type: 'stable', lines: base.slice(pos, cluster.baseStart) })
    }

    const mineLines = resolveSideLines(cluster, 'mine', base, mine)
    const theirsLines = resolveSideLines(cluster, 'theirs', base, theirs)
    const baseLines = base.slice(cluster.baseStart, cluster.baseEnd)

    let kind
    if (arraysEqual(mineLines, theirsLines)) {
      kind = 'both'
    } else if (arraysEqual(mineLines, baseLines)) {
      kind = 'theirs'
    } else if (arraysEqual(theirsLines, baseLines)) {
      kind = 'mine'
    } else {
      kind = 'conflict'
    }

    if (kind === 'conflict') {
      regions.push({ type: 'resolved', kind, mineLines, baseLines, theirsLines })
    } else {
      const lines = kind === 'theirs' ? theirsLines : mineLines
      regions.push({ type: 'resolved', kind, lines, baseLines, mineLines, theirsLines })
    }

    pos = cluster.baseEnd
  }
  if (pos < base.length) {
    regions.push({ type: 'stable', lines: base.slice(pos, base.length) })
  }

  return regions
}
"}

