{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { splitLines, splitDocuments } from './parse.js'
import { buildRegions } from './regions.js'
import { renderMerge, renderRegions } from './format.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('error: usage: cli.js merge|merge2|regions')
    return
  }

  const input = readFileSync(0, 'utf8')
  const lines = splitLines(input)
  const docs = splitDocuments(lines)
  if (docs === null) {
    fail('error: expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = docs

  const regions = buildRegions(mine, base, theirs)

  let rendered
  if (mode === 'merge') {
    rendered = renderMerge(regions, true)
  } else if (mode === 'merge2') {
    rendered = renderMerge(regions, false)
  } else {
    rendered = renderRegions(regions)
  }

  process.stdout.write(rendered.text)
  process.exit(rendered.hasConflict ? 1 : 0)
}

main()
"}

